<?php foreach($products as $p):
$img=product_image($p); $vs=$pdo->prepare('SELECT * FROM product_variants WHERE product_id=? ORDER BY is_default DESC,id');$vs->execute([$p['id']]);$variants=$vs->fetchAll();$default=$variants[0]??['id'=>0,'label'=>'1 Unit','price'=>$p['price'],'mrp'=>$p['mrp'],'stock'=>$p['stock']];$discount=$default['mrp']>0?round((($default['mrp']-$default['price'])/$default['mrp'])*100):0;$available=((float)$default['stock']>0);$productUrl=url(($p['category_slug']??'product').'/'.e($p['slug']).'/');
?><article class="product-card" data-name="<?=e($p['name'])?>" data-product-id="<?=$p['id']?>"><a href="<?=$productUrl?>" class="product-image"><img loading="lazy" decoding="async" width="360" height="360" src="<?=e($img)?>" alt="<?=e($p['image_alt']??$p['name'])?>" onerror="this.onerror=null;this.src='<?=e(url('assets/images/products/no-product-basket.png'))?>';"><?php if($discount>0): ?><span class="discount">-<?=$discount?>%</span><?php endif; ?></a><div class="product-info"><span class="category-label"><?=e($p['category_name'])?></span><h3><a href="<?=$productUrl?>"><?=e($p['name'])?></a></h3><?php if($variants): ?><div class="variant-row"><select class="variant-select" data-product="<?=$p['id']?>"><?php foreach($variants as $v): ?><option value="<?=$v['id']?>" data-price="<?=$v['price']?>" data-mrp="<?=$v['mrp']?>" data-stock="<?=$v['stock']?>"><?=e($v['label'])?></option><?php endforeach; ?></select></div><?php endif; ?><div class="price-row"><strong class="variant-price">₹<?=number_format((float)$default['price'],2)?></strong><del class="variant-mrp"><?=($default['mrp']>$default['price'])?'₹'.number_format((float)$default['mrp'],2):''?></del></div><button type="button" class="btn add-btn add-to-cart" data-product="<?=$p['id']?>" data-variant="<?=$default['id']?>" <?=!$available?'disabled':''?>><?= $available ? 'Add to Cart' : 'Coming Soon' ?></button></div></article><?php endforeach; ?>